check_code:
cw={"TL":"TR","TR":"BR","BR":"BL","BL":"TL"}
flip={"A":"invA","invA":"A","up":"down","down":"up","P":"b","b":"P","tri_dn":"tri_up","tri_up":"tri_dn"}
def step(f):
    g={}
    for p,s in f.items():
        q=cw[p]; g[q]=flip[s] if p=="BL" else s
    return g
f1={"TL":"A","TR":"tri_dn","BL":"up","BR":"P"}
seq=[f1]
for _ in range(4): seq.append(step(seq[-1]))
assert seq[1]=={"TL":"down","TR":"A","BR":"tri_dn","BL":"P"}
assert seq[3]=={"TL":"tri_up","TR":"b","BR":"down","BL":"A"}
ans=seq[4]
opts={"A":{"TL":"invA","TR":"tri_up","BL":"down","BR":"b"},
      "B":{"TL":"A","TR":"tri_dn","BL":"down","BR":"b"},
      "C":{"TL":"A","TR":"tri_up","BL":"down","BR":"b"},
      "D":{"TL":"invA","TR":"tri_up","BL":"up","BR":"b"}}
assert ans==opts["A"]
for k in "BCD": assert ans!=opts[k]

def unfold(holes, vfold, hfold):
    # holes in quarter coords (x,y) with quarter at given place in unit square [0,1]^2; reflect across x=0.5 and y=0.5
    pts=set()
    for (x,y,k) in holes:
        for X in (x,1-x):
            for Y in (y,1-y):
                pts.add((round(X,2),round(Y,2),k))
    return pts

holes=[(0.65,0.62,"c"),(0.9,0.9,"o")]
pts=unfold(holes,True,True)
n=len(pts)
opts={"A":6,"B":8,"C":4,"D":6}
assert n==opts["B"]
for k in "ACD": assert n!=opts[k]
